from typing import Annotatedfrom pydantic import AfterValidator, FieldBCRYPT_MAX_BYTES = 72def _fits_bcrypt(value: str) -> str:    # bcrypt reads at most 72 BYTES and bcrypt 5 raises on more. 72 characters can be up to    # 288 bytes in UTF-8 (e.g. "é" is 2 bytes), so the character limit alone is not enough.    if len(value.encode()) > BCRYPT_MAX_BYTES:        raise ValueError(f"Password must be at most {BCRYPT_MAX_BYTES} bytes")    return valueLoginPassword = Annotated[str, Field(min_length=1, max_length=72), AfterValidator(_fits_bcrypt)]NewPassword = Annotated[str, Field(min_length=8, max_length=72), AfterValidator(_fits_bcrypt)]